// Format HTML Newsletter
// Input: { total, stats, articles, gptReport }

const data = $input.first().json || {};
const gptReport = data.gptReport || 'Relatório não gerado.';
const total = data.total || 0;
const stats = data.stats || [];
const articles = data.articles || [];

const topStat = stats.length > 0 ? stats[0] : null;

function esc(str) {
  if (!str) return '';
  return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#039;');
}

const statsRows = stats.map(s =>
  '<tr><td>' + esc(s.category) + '</td><td>' + (s.count || 0) + '</td><td>' + (s.percentage || 0) + '%</td></tr>'
).join('');

const byCategory = {};
articles.forEach(a => {
  const cat = a.category || 'General AI';
  if (!byCategory[cat]) byCategory[cat] = [];
  byCategory[cat].push(a);
});

const articleSections = Object.entries(byCategory).map(([cat, arts]) => {
  const artList = arts.map(a =>
    '<li><a href="' + esc(a.link || '#') + '" target="_blank">' + esc(a.title || 'Sem título') + '</a>' +
    (a.summary ? '<br><small>' + esc(a.summary) + '</small>' : '') +
    '</li>'
  ).join('');
  return '<h3>' + esc(cat) + '</h3><ul>' + artList + '</ul>';
}).join('');

// Convert markdown from GPT to HTML
const reportHtml = gptReport
  .replace(/^### (.+)$/gim, '<h3>$1</h3>')
  .replace(/^## (.+)$/gim, '<h2>$1</h2>')
  .replace(/^# (.+)$/gim, '<h1>$1</h1>')
  .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
  .replace(/\*(.+?)\*/g, '<em>$1</em>')
  .replace(/`(.+?)`/g, '<code>$1</code>')
  .replace(/^- (.+)$/gim, '<li>$1</li>')
  .replace(/^(\d+)\. (.+)$/gim, '<li>$2</li>')
  .replace(/\n\n/g, '</p><p>')
  .replace(/\n/g, '<br>');

const weekDate = new Date().toLocaleDateString('pt-BR', {
  day: '2-digit',
  month: 'long',
  year: 'numeric'
});

const html = '<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>AI News - Inteli Academy</title><style>body{font-family:Arial,sans-serif;background:#f5f5f5;padding:20px;color:#111;line-height:1.6}.container{max-width:800px;margin:auto;background:#fff;padding:30px}.header{background:linear-gradient(135deg,#1a1a2e,#16213e);color:#fff;padding:30px;margin:-30px -30px 20px}.header h1{font-size:28px;margin:0 0 4px}.header .subtitle{color:#a0aec0;font-size:14px}.summary{background:#111;color:#fff;padding:20px;display:flex;justify-content:space-around;margin-bottom:20px}.summary div{text-align:center}.summary .num{font-size:24px;font-weight:bold}.summary .label{font-size:12px;color:#a0aec0}table{width:100%;border-collapse:collapse;margin:16px 0 24px}th{text-align:left;padding:10px 12px;background:#f7fafc;border-bottom:2px solid #e2e8f0;font-size:13px;color:#718096;text-transform:uppercase}td{padding:10px 12px;border-bottom:1px solid #e2e8f0}h2{font-size:20px;margin:24px 0 12px;padding-bottom:8px;border-bottom:2px solid #e2e8f0}h3{font-size:16px;margin:16px 0 8px;color:#2d3748}ul{padding-left:20px;margin-bottom:12px}li{margin-bottom:8px}.footer{background:#f7fafc;padding:20px 30px;text-align:center;color:#718096;font-size:12px;margin:20px -30px -30px;border-top:1px solid #e2e8f0}@media(max-width:600px){body{padding:10px}.container{padding:16px}.header,.summary,.footer{margin:0;padding:16px}}</style></head><body><div class="container"><div class="header"><h1>Inteli Academy &#8211; AI News</h1><div class="subtitle">' + esc(weekDate) + '</div></div><div class="summary"><div><div class="num">' + total + '</div><div class="label">Noticias</div></div><div><div class="num">' + stats.length + '</div><div class="label">Categorias</div></div><div><div class="num">' + (topStat ? (topStat.percentage || 0) + '%' : '-') + '</div><div class="label">' + (topStat ? esc(topStat.category) : '-') + '</div></div></div><h2>Distribuicao por Categoria</h2><table><thead><tr><th>Categoria</th><th>Noticias</th><th>%</th></tr></thead><tbody>' + statsRows + '</tbody></table>' + reportHtml + '<h2>Noticias Completas</h2>' + articleSections + '<div class="footer">Gerado automaticamente por Inteli Academy AI News Aggregator</div></div></body></html>';

return [{
  json: {
    html: html,
    subject: 'AI News | ' + weekDate,
    total: total
  }
}];

const items = ($input.all() || []).filter(i => i && i.json);

const categoryCounts = {
  'Generative AI': 0,
  'Machine Learning': 0,
  'Computer Vision': 0,
  'AI Ethics & Regulation': 0,
  'AI in Healthcare': 0,
  'AI in Finance': 0,
  'AI Infrastructure': 0,
  'AI Startups & Business': 0,
  'General AI': 0
};

const articles = items.map(i => {
  const j = i.json;
  const cat = j.category || 'General AI';
  if (categoryCounts.hasOwnProperty(cat)) {
    categoryCounts[cat] = (categoryCounts[cat] || 0) + 1;
  } else {
    categoryCounts['General AI']++;
  }
  return {
    title: j.title || 'Sem titulo',
    link: j.link || j.url || '',
    summary: (j.contentSnippet || j.summary || '').slice(0, 300),
    date: j.pubDate || j.isoDate || j.date || '',
    category: cat
  };
});

const total = articles.length;

const stats = Object.entries(categoryCounts)
  .filter(([, count]) => count > 0)
  .map(([cat, count]) => ({
    category: cat,
    count,
    percentage: total > 0 ? Math.round((count / total) * 100) : 0
  }))
  .sort((a, b) => b.count - a.count);

const safeArticles = articles.length > 0 ? articles : [{
  title: 'Nenhuma noticia encontrada',
  link: '',
  summary: 'Nao houve noticias relevantes de IA nesta semana.',
  date: new Date().toISOString(),
  category: 'General AI'
}];

const statsText = stats
  .map(s => '- ' + s.category + ': ' + s.count + ' noticias (' + s.percentage + '%)')
  .join('\n');

const articlesText = safeArticles
  .map((a, i) => (i + 1) + '. [' + a.category + '] ' + a.title + '\n   ' + a.summary + '\n   Link: ' + a.link)
  .join('\n\n');

const prompt = 'Voce e um analista especializado em Inteligencia Artificial. Analise as seguintes noticias da semana e gere um relatorio completo em portugues.\n\n' +
  'Total de noticias coletadas: ' + total + '\n\n' +
  'Estatisticas por categoria:\n' + statsText + '\n\n' +
  'Noticias da semana:\n' + articlesText + '\n\n' +
  'Gere um relatorio estruturado com as seguintes secoes:\n\n' +
  '## DESTAQUES DA SEMANA\n' +
  'Liste as 5 noticias mais relevantes e impactantes, com breve analise de cada uma.\n\n' +
  '## NOTICIAS POR CATEGORIA\n' +
  'Resuma os principais acontecimentos em cada categoria que teve noticias.\n\n' +
  '## TENDENCIAS EMERGENTES\n' +
  'Identifique 3 a 5 tendencias claras observadas no conjunto de noticias desta semana.\n\n' +
  '## OPORTUNIDADES PARA STARTUPS\n' +
  'Identifique 3 a 5 lacunas ou oportunidades de mercado reveladas pelas noticias, com justificativa.\n\n' +
  '## TOPICOS SUB-REPRESENTADOS\n' +
  'Aponte 2 a 3 temas importantes de IA que estao ausentes ou pouco cobertos nesta semana.\n\n' +
  '## RESUMO EXECUTIVO\n' +
  'Um paragrafo sintetico com os principais insights da semana para liderancas e tomadores de decisao.\n\n' +
  'Seja objetivo, analitico e use linguagem profissional. Nao use emojis.';

return [{
  json: {
    total,
    stats,
    articles: safeArticles,
    prompt
  }
}];

const aiKeywords = [
  'ai', 'artificial intelligence', 'machine learning', 'deep learning',
  'gpt', 'llm', 'large language model', 'neural', 'openai', 'anthropic',
  'gemini', 'claude', 'mistral', 'llama', 'diffusion', 'stable diffusion',
  'generative', 'transformer', 'reinforcement learning', 'computer vision',
  'natural language', 'nlp', 'chatgpt', 'chatbot', 'autonomous',
  'foundation model', 'multimodal', 'fine-tuning', 'embedding',
  'inference', 'model', 'automation', 'robot', 'robotics', 'gpu', 'tpu',
  'nvidia', 'hugging face', 'langchain', 'vector database', 'rag',
  'agent', 'agi', 'synthetic data', 'copilot', 'ai assistant'
];

const categoryKeywords = {
  'Generative AI': ['gpt', 'llm', 'large language model', 'generative', 'diffusion', 'stable diffusion', 'dalle', 'midjourney', 'claude', 'gemini', 'llama', 'mistral', 'multimodal', 'text generation', 'image generation', 'foundation model'],
  'Machine Learning': ['machine learning', 'deep learning', 'neural network', 'neural', 'fine-tuning', 'training', 'reinforcement learning', 'embedding', 'transformer', 'rag', 'retrieval'],
  'Computer Vision': ['computer vision', 'image recognition', 'object detection', 'video', 'ocr', 'visual', 'camera', 'perception'],
  'AI Ethics & Regulation': ['ethics', 'regulation', 'governance', 'policy', 'bias', 'fairness', 'safety', 'alignment', 'responsible ai', 'eu ai act', 'legislation', 'compliance', 'risk'],
  'AI in Healthcare': ['health', 'medical', 'drug discovery', 'diagnosis', 'clinical', 'patient', 'hospital', 'radiology', 'genomics', 'biotech'],
  'AI in Finance': ['finance', 'fintech', 'fraud', 'trading', 'banking', 'investment', 'credit', 'risk management', 'insurance'],
  'AI Infrastructure': ['gpu', 'tpu', 'chip', 'hardware', 'cloud', 'edge computing', 'inference', 'nvidia', 'amd', 'data center', 'compute', 'infrastructure'],
  'AI Startups & Business': ['startup', 'funding', 'acquisition', 'valuation', 'series', 'venture', 'ipo', 'revenue', 'enterprise', 'saas']
};

const sevenDaysAgo = new Date();
sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);

return ($input.all() || [])
  .filter(item => item && item.json)
  .map(item => {
    const json = item.json;
    const title = String(json.title || '');
    const content = String(json.contentSnippet || json.content || json.summary || '');
    const text = (title + ' ' + content).toLowerCase();
    let date;
    const raw = json.pubDate || json.isoDate || json.date || json.publishedDate;
    try {
      date = new Date(raw);
      if (isNaN(date.getTime())) date = new Date();
    } catch (e) {
      date = new Date();
    }

    let category = 'General AI';
    for (const [cat, keywords] of Object.entries(categoryKeywords)) {
      if (keywords.some(k => text.includes(k))) {
        category = cat;
        break;
      }
    }

    return {
      json: {
        ...json,
        _text: text,
        _date: date.toISOString(),
        category
      }
    };
  })
  .filter(item => {
    const text = item.json._text;
    const date = new Date(item.json._date);
    const isAI = aiKeywords.some(k => text.includes(k));
    const isRecent = date >= sevenDaysAgo;
    return isAI && isRecent;
  })
  .map(item => {
    delete item.json._text;
    delete item.json._date;
    return item;
  });

const seen = new Set();

return $input.all().filter(item => {
  if (!item || !item.json) return false;
  const uniqueKey = item.json.link || item.json.url || item.json.guid || item.json.id || item.json.title;
  if (!uniqueKey) return false;
  const key = String(uniqueKey);
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
});

const aggData = $('Aggregate & Count by Category').first().json;
const gptItem = $input.first().json;

let text = gptItem?.text || gptItem?.message || JSON.stringify(gptItem) || 'Relatório não gerado.';

return [{
  json: {
    total: aggData.total,
    stats: aggData.stats,
    articles: aggData.articles,
    gptReport: text
  }
}];
